import os
import json
from load import course
import sys
legs = json.load(open(sys.argv[1] if len(sys.argv) > 1 else "legs.json"))
cps, _, _ = course()
targets = {"L1": cps[1], "L2": cps[2], "L3": cps[3], "L4": cps[4], "L5": cps[5]}
out = ["-- GENERATED by tools/race-paths/make_course_data.py from a terrain survey taken DURING a race",
       "-- (the race map adds rock walls and ridges the open world does not have); do not edit by hand.",
       "-- Walking routes per race leg, in UE units (cm): the leg is the one whose `to` matches the HUD's",
       "-- next checkpoint. A point with a 4th field `true` is the foot of a ledge: jump there; 'launch'",
       "-- marks a floating booster above the point: stop under it, then jump into it.",
       "-- Source and method: reference/dbz-kakarot/notes/dbz-kakarot-race-minigame.md",
       "return {", "    {", '        name = "Area03 walking robot",', "        legs = {"]
for name, pts in legs:
    t = targets[name]
    out.append("            {")
    out.append("                to = { %d, %d, %d }," % (t[1], t[2], t[3]))
    out.append("                pts = {")
    for k, p in enumerate(pts):
        f = p[3] if len(p) > 3 else None
        extra = ", true" if (f == "j" and k < len(pts) - 1) else (', "launch"' if f == "launch" else "")
        out.append("                    { %d, %d, %d%s }," % (round(p[0]), round(p[1]), round(p[2]), extra))
    out.append("                },")
    out.append("            },")
out += ["        },", "    },", "}"]
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "mod", "KakarotAccess", "Scripts", "race_courses.lua"), "w", encoding="utf-8").write("\n".join(out) + "\n")
print("written")
